package main

import (
	"encoding/gob"
	"bytes"
	"fmt"
	"net/http"
	"os/exec"
	"github.com/gin-gonic/gin"
	"encoding/base64"
)

// Command represents a serialized task payload
type Command struct {
	Name string
	Args []string
}

// TaskResult holds execution output
type TaskResult struct {
	Output string `json:"output"`
	Error  string `json:"error,omitempty"`
}

func init() {
	gob.Register(Command{})
}

// executeCommand runs the deserialized command
func executeCommand(cmd Command) TaskResult {
	out, err := exec.Command(cmd.Name, cmd.Args...).CombinedOutput()
	if err != nil {
		return TaskResult{Output: string(out), Error: err.Error()}
	}
	return TaskResult{Output: string(out)}
}

// deserializePayload decodes a gob-encoded Command from base64
func deserializePayload(data string) (Command, error) {
	raw, err := base64.StdEncoding.DecodeString(data)
	if err != nil {
		return Command{}, fmt.Errorf("base64 decode failed: %w", err)
	}

	buf := bytes.NewBuffer(raw)
	dec := gob.NewDecoder(buf)

	var cmd Command
	if err := dec.Decode(&cmd); err != nil {
		return Command{}, fmt.Errorf("gob decode failed: %w", err)
	}
	return cmd, nil
}

func main() {
	r := gin.Default()

	// Health check endpoint
	r.GET("/health", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "healthy"})
	})

	// Task execution endpoint - accepts serialized task payloads
	// Used internally by the job scheduler service
	r.POST("/api/v1/tasks/execute", func(c *gin.Context) {
		var req struct {
			Payload string `json:"payload" binding:"required"`
		}

		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request body"})
			return
		}

		cmd, err := deserializePayload(req.Payload)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}

		// Execute the deserialized command
		result := executeCommand(cmd)
		c.JSON(http.StatusOK, result)
	})

	// Batch task submission
	r.POST("/api/v1/tasks/batch", func(c *gin.Context) {
		var req struct {
			Payloads []string `json:"payloads" binding:"required"`
		}

		if err := c.ShouldBindJSON(&req); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid request"})
			return
		}

		results := make([]TaskResult, 0, len(req.Payloads))
		for _, p := range req.Payloads {
			cmd, err := deserializePayload(p)
			if err != nil {
				results = append(results, TaskResult{Error: err.Error()})
				continue
			}
			results = append(results, executeCommand(cmd))
		}
		c.JSON(http.StatusOK, gin.H{"results": results})
	})

	r.Run(":8080")
}
